# 0.1.8: a hub bar click (HubBar.handle FIRST, HUBS-CONTRACT 2.6): the X closes; "< Menu" (/skymenu), another tab (its open Function or
# its command) and the Auctions tab itself are done (no redraw: typed search / price stay); a tab that could not open (hidden / missing /
# failed) answers on the status line. false = not a hub click (the page goes on as 0.1.7).
# review fix (2026-10-15): a handled hub click that leaves this page open (its own tab, "< Menu" / a command still on its way, a
# Function that answered TRUE without a page) is ANSWERED - a no-op update (the hub title set to itself): the client's "Loading..."
# ends and typed text stays. Never to a page that is no longer the open page (another tab replaced it).
M(page, r"""
public void hubAck() {
  try {
    com.hypixel.hytale.component.Ref hr = this.playerRef.getReference();
    if (hr == null || !hr.isValid()) return;
    com.hypixel.hytale.component.Store hs = hr.getStore();
    if (hs == null) return;
    com.hypixel.hytale.server.core.entity.entities.Player hp = (com.hypixel.hytale.server.core.entity.entities.Player) hs.getComponent(hr, com.hypixel.hytale.server.core.entity.entities.Player.getComponentType());
    if (hp == null || hp.getPageManager() == null || hp.getPageManager().getCustomPage() != this) return;
    com.hypixel.hytale.server.core.ui.builder.UICommandBuilder hb = new com.hypixel.hytale.server.core.ui.builder.UICommandBuilder();
    hb.set("#SkyyAhFTitle.Text", "Market");
    sendUpdate(hb, false);
  } catch (Throwable t) { }
}""")
M(page, r"""
public boolean hubClick(String data) {
  String r = null;
  try { r = @PKG@.HubBar.route(this.playerRef, data, "market", myTab()); } catch (Throwable t) { r = null; }   // 0.1.10: rows 1 + 2 (kit 1.7)
  if (r == null) return false;
  if (r.equals("close")) { try { close(); } catch (Throwable tc) { @PKG@.AhUtil.warn("auction page hub close failed: " + tc); } return true; }
  // 0.1.10: the page's own tab in row 2 (the Market tab) leads back to the list from an item's page (no back button - rule 8)
  if (r.equals("self") && "item".equals(this.view)) { this.view = "browse"; try { rebuild(); } catch (Throwable tr) { } return true; }
  if (r.equals("self") || r.equals("back") || r.equals("bridge") || r.equals("command")) { hubAck(); return true; }
  say("That tab could not open right now - try again.", 2);
  try { rebuild(); } catch (Throwable tr) { }
  return true;
}""")
# 0.1.9 MARKET MERGE: BAZAAR - the Bazaar page through SkyyBazaar's bazaar:fn:open WITH this page's search (the one search follows the
# player); else its hub tab (open Function / command, HubBar.open); TRUE = handled (another page opened, or a command is on its way and this
# page was answered); FALSE = nothing opened (the status line says so, the caller redraws)
M(page, r"""
public boolean mkBazaar(java.util.UUID u) {
  Object f = null;
  try { f = @PKG@.AhUtil.bridge().get("bazaar:fn:open"); } catch (Throwable t) { f = null; }
  String q = this.query == null ? "" : this.query;
  if (f instanceof java.util.function.Function) {
    Object r = null;
    try { r = ((java.util.function.Function) f).apply(new Object[] { u, q }); } catch (Throwable t) { r = null; }
    if (Boolean.TRUE.equals(r)) { hubAck(); return true; }   // answered (a no-op when the Bazaar page replaced this one)
  }
  String h = null;
  try { h = @PKG@.HubBar.open(this.playerRef, u, "market", "bazaar"); } catch (Throwable t) { h = null; }
  if ("bridge".equals(h) || "command".equals(h)) { hubAck(); return true; }   // answered unless another page replaced this one
  say("The Bazaar is not on this server right now.", 2);
  return false;
}""")
M(page, r"""
public void handleDataEvent(@REF@ ref, @ST@ st, String data) {
  if (hubClick(data)) return;   // 0.1.8: the hub bar
  try {
    if (data == null) return;
    String a = @PKG@.AhUtil.jsonStr(data, "a");
    if (a.length() == 0) return;
    java.util.UUID u = this.playerRef.getUuid();
    long now = System.currentTimeMillis();
    String wAct = this.armAct;
    String wId = this.armId;
    long wPrice = this.armPrice;
    long wUntil = this.armUntil;
    this.armAct = null; this.armId = null; this.armPrice = 0L; this.armUntil = 0L;
    String lvBad = readFields(data);
    if (data.indexOf("\"@AhPrice\"") >= 0) {
      String v = @PKG@.AhUtil.jsonStr(data, "@AhPrice").trim();
      if (v.length() > 16) v = v.substring(0, 16);
      this.priceText = v;
    }
    @PLA@ p = null;
    try { p = (@PLA@) st.getComponent(ref, @PLA@.getComponentType()); } catch (Throwable t) { p = null; }
    if (a.equals("close")) { if (p != null) p.getPageManager().setPage(ref, st, @PGE@.None); return; }
    if (a.equals("mk:bz")) { if (mkBazaar(u)) return; rebuild(); return; }   // 0.1.9: the sub-view switch (readFields kept the search text)
    String k = @PKG@.AhUtil.pkey(u);
    if (!k.equals(this.key)) {
      this.key = k;
      this.pickSec = -1; this.pickSlot = -1; this.pickSig = ""; this.previewPrice = -1L; this.managePage = 0;
      String pn = @PKG@.AhUtil.profName(u);
      say("Your profile changed - this is now profile " + (pn.length() > 0 ? pn : "(current)") + "'s view.", 2);
      rebuild();
      return;
    }
    this.status = ""; this.statusKind = 0;
    if (a.equals("nav:browse")) { this.view = "browse"; }
    else if (a.equals("nav:create") || a.equals("mcreate")) { this.view = "create"; }
    else if (a.equals("nav:manage")) { this.view = "manage"; }
    else if (browseAct(a)) { }
    else if (a.startsWith("view:")) {
      int i = argInt(a, "view:");
      if (i >= 0 && this.rowIds != null && i < this.rowIds.length && this.rowIds[i] != null) { this.detailId = this.rowIds[i]; this.detailPrice = -1L; this.view = "item"; }
    }
    else if (a.equals("back")) { this.view = "browse"; }
    else if (a.equals("buy")) { doBuy(ref, st, p, u, now, false); }
    else if (a.equals("confirm")) {
      if (armOk(wAct, wId, wPrice, wUntil, "buy", this.detailId, this.detailPrice, now)) doBuy(ref, st, p, u, now, true);
      else if (armOk(wAct, wId, wPrice, wUntil, "cancel", this.detailId, this.detailPrice, now)) doCancel(ref, st, p, u, this.detailId);
      else say("The confirm ran out - click again.", 2);
    }
    else if (a.equals("no")) { say("Nothing done.", 0); }
    else if (a.equals("dcancel")) {
      @BD@ r = @PKG@.AhStore.get(this.detailId);
      if (r != null && this.key.equals(@PKG@.AhRec.subStr(r, "seller", "key", ""))) { arm("cancel", this.detailId, this.detailPrice, now); say("Confirm the cancel within " + (@PKG@.AhCfg.CONFIRM_MS / 1000L) + " s.", 0); }
      else say("That listing is not yours or is gone.", 2);
    }
    else if (a.startsWith("pick:")) {
      int i = argInt(a, "pick:");
      if (i >= 0 && this.cellSec != null && i < this.cellSec.length && this.cellSec[i] >= 0 && p != null) {
        @IC@ c = @PKG@.AhItem.section(p, this.cellSec[i]);
        @IS@ x = c == null ? null : c.getItemStack((short) this.cellSlot[i]);
        if (x == null || x.isEmpty() || !@PKG@.AhItem.sig(x).equals(this.cellSig[i])) say("That slot changed - pick again.", 2);
        else {
          String why = @PKG@.AhItem.tradeable(x);
          if (why != null) say(why, 2);
          else { this.pickSec = this.cellSec[i]; this.pickSlot = this.cellSlot[i]; this.pickSig = this.cellSig[i]; say("Picked " + @PKG@.AhItem.stackName(x) + " - type a price.", 0); }
        }
      }
    }
    // 0.1.10: invprev / invnext went (the inventory picker is ONE scroll list)
    else if (a.equals("preview")) { doPreview(); }
    else if (a.startsWith("dur:")) { int i = argInt(a, "dur:"); if (i >= 0 && i < @PKG@.AhCfg.DUR_LABEL.length) this.durIdx = i; doPreview(); }
    else if (a.equals("create")) { doCreate(ref, st, p, u); }
    else if (a.startsWith("mact:")) {
      int i = argInt(a, "mact:");
      if (i >= 0 && this.mIds != null && i < this.mIds.length && this.mIds[i] != null) {
        String kind = this.mKinds[i];
        if (kind.equals("active")) { arm("mcancel:" + i, this.mIds[i], 0L, now); say("Cancel it? The fee is " + (@PKG@.AhCfg.CANCEL_REFUND ? "refunded" : "not refunded") + " - click Yes, cancel within " + (@PKG@.AhCfg.CONFIRM_MS / 1000L) + " s.", 0); }
        else if (kind.equals("coins")) { @RES@ r = @PKG@.AhStore.claimCoins(u, this.key, this.mIds[i]); finish(r, ref, st, p); say(r.msg, r.ok ? 1 : 2); }
        else if (kind.equals("sitem") || kind.equals("bitem")) { @RES@ r = @PKG@.AhStore.claimItem(p, u, this.key, this.mIds[i], kind.equals("sitem")); finish(r, ref, st, p); say(r.msg, r.ok ? 1 : 2); }
      }
    }
    else if (a.startsWith("myes:")) {
      int i = argInt(a, "myes:");
      if (i >= 0 && this.mIds != null && i < this.mIds.length && this.mIds[i] != null && armOk(wAct, wId, wPrice, wUntil, "mcancel:" + i, this.mIds[i], 0L, now)) doCancel(ref, st, p, u, this.mIds[i]);
      else say("The confirm ran out - click Cancel again.", 2);
    }
    else if (a.equals("mno") || a.equals("claimno")) { say("Nothing done.", 0); }
    // 0.1.10: mprev / mnext went (Manage is ONE scroll list)
    else if (a.equals("claimall")) {
      long[] ow = @PKG@.AhStore.owedFor(this.key);
      if (@PKG@.AhCfg.CLAIMALL_ABOVE > 0L && ow[1] >= @PKG@.AhCfg.CLAIMALL_ABOVE) { arm("claimall", String.valueOf(ow[1]), ow[1], now); say("Purse coins can be lost on death - coins waiting here are safe.", 0); }
      else doClaimAll(ref, st, p, u);
    }
    else if (a.equals("claimyes")) {
      long[] ow = @PKG@.AhStore.owedFor(this.key);
      if (armOk(wAct, wId, wPrice, wUntil, "claimall", String.valueOf(ow[1]), ow[1], now)) doClaimAll(ref, st, p, u);
      else say("The confirm ran out or the amount changed - click Claim all again.", 2);
    }
    if (lvBad != null && this.status.length() == 0) say(lvBad, 2);
    rebuild();
  } catch (Throwable t) { @PKG@.AhUtil.warn("auction page click failed: " + t); }
}""")

