# find: one row per item id; internal row Object[]{ id, name, Integer n, Long each, Long price, Long qty, Long endsMs, Integer level, color,
# Long numId of the cheapest } -> the contract row (endsIn as text, 9 elements)
M(mfn, r"""
public Object find(Object o) {
  java.util.ArrayList out = new java.util.ArrayList();
  String q = null;
  if (o instanceof String) q = (String) o;
  else if ((o instanceof Object[]) && ((Object[]) o).length > 0 && (((Object[]) o)[0] instanceof String)) q = (String) ((Object[]) o)[0];
  if (q == null) return out;
  String n = q.trim().toLowerCase();
  if (n.length() > 40) n = n.substring(0, 40);
  if (n.length() == 0) return out;
  String[] w = n.split("\\s+");
  long now = System.currentTimeMillis();
  java.util.ArrayList all = @PKG@.AhStore.active(now);
  java.util.HashMap by = new java.util.HashMap();
  java.util.ArrayList order = new java.util.ArrayList();
  for (int i = 0; i < all.size(); i++) {
    @BD@ r = (@BD@) all.get(i);
    String iid = @PKG@.AhRec.subStr(r, "item", "id", "");
    if (iid.length() == 0 || @PKG@.AhItem.blockedReason(iid) != null) continue;
    String hay = @PKG@.AhRec.str(r, "search", "") + " " + iid.toLowerCase() + " " + iid.replace('_', ' ').toLowerCase();
    boolean ok = true;
    for (int k = 0; k < w.length; k++) { if (w[k].length() > 0 && hay.indexOf(w[k]) < 0) ok = false; }
    if (!ok) continue;
    long qty = @PKG@.AhRec.subLng(r, "item", "qty", 1L);
    if (qty < 1L) qty = 1L;
    long price = @PKG@.AhRec.lng(r, "price", 0L);
    long each = @PKG@.AhUtil.ceilDiv(price, qty);
    long ends = @PKG@.AhRec.lng(r, "endsAt", 0L) - now;
    long num = @PKG@.AhRec.numId(r);
    Object[] e = (Object[]) by.get(iid);
    if (e == null) {
      e = new Object[10];
      e[0] = iid;
      e[2] = Integer.valueOf(0);
      e[6] = Long.valueOf(ends);
      by.put(iid, e);
      order.add(iid);
    }
    e[2] = Integer.valueOf(((Integer) e[2]).intValue() + 1);
    if (ends < ((Long) e[6]).longValue()) e[6] = Long.valueOf(ends);
    boolean cheaper = e[3] == null || each < ((Long) e[3]).longValue() || (each == ((Long) e[3]).longValue() && num < ((Long) e[9]).longValue());
    if (cheaper) {
      String nm = @PKG@.AhItem.dispName(r);
      e[1] = (nm == null || nm.length() == 0) ? iid : nm;
      e[3] = Long.valueOf(each);
      e[4] = Long.valueOf(price);
      e[5] = Long.valueOf(qty);
      int lv = @PKG@.AhItem.levelOfRec(r);
      e[7] = Integer.valueOf(lv < 0 ? -1 : lv);
      String c = @PKG@.AhItem.dispColor(r);
      e[8] = c == null ? "" : c;
      e[9] = Long.valueOf(num);
    }
  }
  for (int i = 0; i < order.size() && out.size() < 300; i++) {
    Object[] e = (Object[]) by.get(order.get(i));
    out.add(new Object[] { e[0], e[1], e[2], e[3], e[4], e[5], @PKG@.AhUtil.timeLeft(((Long) e[6]).longValue()), e[7], e[8] });
  }
  return out;
}""")
# open: the player's world thread (the caller is the Bazaar page's event): the Auction House on Browse with that search, as /ah opens it
