# 0.1.10 ah:fn:view (op 2, KEY CONTRACT in tools/auctions_0_1_10_patch.py): Object[]{ UUID, "browse" | "create" | "manage" } opens the Auction
# House on that view for the player (world thread, as /ah opens it) -> Boolean; a UUID alone -> Long = the claims waiting for that player's
# current profile (AhStore.owedFor(pkey)[0]) - SkyyBazaar 0.1.18's CREATE BIN / MANAGE (n) sub-tabs
M(mfn, r"""
public Object view(Object o) {
  if (o instanceof java.util.UUID) {
    long[] ow = @PKG@.AhStore.owedFor(@PKG@.AhUtil.pkey((java.util.UUID) o));
    return Long.valueOf(ow == null || ow.length < 1 ? 0L : ow[0]);
  }
  if (!(o instanceof Object[])) return Boolean.FALSE;
  Object[] a = (Object[]) o;
  if (a.length < 2 || !(a[0] instanceof java.util.UUID) || !(a[1] instanceof String)) return Boolean.FALSE;
  String v = (String) a[1];
  if (!v.equals("browse") && !v.equals("create") && !v.equals("manage")) return Boolean.FALSE;
  try {
    @PR@ pr = @UNI@.get().getPlayer((java.util.UUID) a[0]);
    if (pr == null || !pr.isValid()) return Boolean.FALSE;
    @REF@ r = pr.getReference();
    if (r == null || !r.isValid()) return Boolean.FALSE;
    @ST@ st = r.getStore();
    if (st == null) return Boolean.FALSE;
    @PLA@ p = (@PLA@) st.getComponent(r, @PLA@.getComponentType());
    if (p == null || p.getPageManager() == null) return Boolean.FALSE;
    @PKG@.AhCmds.open(pr, r, st, new @PKG@.AhPage(pr, v));
    return Boolean.TRUE;
  } catch (Throwable t) {
    @PKG@.AhUtil.warn("ah:fn:view could not open the Auction House: " + t);
    return Boolean.FALSE;
  }
}""")
M(mfn, r"""
public Object apply(Object o) {
  try {
    if (this.op == 2) return view(o);
    if (this.op == 1) return open(o);
    return find(o);
  } catch (Throwable t) {
    @PKG@.AhUtil.warn("ah:fn:" + (this.op == 2 ? "view" : (this.op == 1 ? "open" : "find")) + " failed: " + t);
    if (this.op == 2) return (o instanceof java.util.UUID) ? (Object) Long.valueOf(0L) : (Object) Boolean.FALSE;
    if (this.op == 1) return Boolean.FALSE;
    return new java.util.ArrayList();
  }
}""")
